function NavbarGlass() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${scrolled ? 'bg-white/80 backdrop-blur-xl shadow-lg' : 'bg-transparent'}`}>
      <div className="max-w-7xl mx-auto px-6">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <a href="#" className={`text-xl font-bold ${scrolled ? 'text-gray-900' : 'text-white'}`}>
            Brand
          </a>
          {/* Nav Links */}
          <div className="hidden md:flex items-center gap-8">
            {['Features', 'Pricing', 'About', 'Contact'].map(item => (
              <a 
                key={item} 
                href={`#${item.toLowerCase()}`}
                className={`text-sm font-medium transition-colors ${scrolled ? 'text-gray-600 hover:text-gray-900' : 'text-white/80 hover:text-white'}`}
              >
                {item}
              </a>
            ))}
          </div>
          {/* CTA */}
          <button className={`px-5 py-2 rounded-full text-sm font-medium transition-all ${scrolled ? 'bg-black text-white hover:bg-gray-800' : 'bg-white text-black hover:bg-gray-100'}`}>
            Get Started
          </button>
        </div>
      </div>
    </nav>
  );
}

