function NavbarResponsive() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <nav className="bg-white shadow-sm">
      <div className="max-w-7xl mx-auto px-6">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <a href="#" className="text-xl font-bold text-gray-900">Brand</a>
          {/* Desktop Nav */}
          <div className="hidden md:flex items-center gap-8">
            {['Features', 'Pricing', 'About'].map(item => (
              <a key={item} href="#" className="text-gray-600 hover:text-gray-900 transition-colors">{item}</a>
            ))}
            <button className="px-5 py-2 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 transition-colors">
              Sign Up
            </button>
          </div>
          {/* Mobile Menu Button */}
          <button 
            className="md:hidden p-2"
            onClick={() => setIsOpen(!isOpen)}
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              {isOpen ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              )}
            </svg>
          </button>
        </div>
        {/* Mobile Menu */}
        {isOpen && (
          <div className="md:hidden py-4 border-t border-gray-100">
            {['Features', 'Pricing', 'About'].map(item => (
              <a key={item} href="#" className="block py-3 text-gray-600 hover:text-gray-900">{item}</a>
            ))}
            <button className="w-full mt-4 px-5 py-3 bg-blue-600 text-white font-medium rounded-lg">
              Sign Up
            </button>
          </div>
        )}
      </div>
    </nav>
  );
}
